import{_ as o,o as a,c as l,ag as r}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"穷忙陷阱：越努力越原地踏步","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/philosophy/poverty-busy-trap.md","filePath":"topics/philosophy/poverty-busy-trap.md"}'),i={name:"topics/philosophy/poverty-busy-trap.md"};function n(s,t,e,u,d,h){return a(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="穷忙陷阱-越努力越原地踏步" tabindex="-1">穷忙陷阱：越努力越原地踏步 <a class="header-anchor" href="#穷忙陷阱-越努力越原地踏步" aria-label="Permalink to &quot;穷忙陷阱：越努力越原地踏步&quot;">​</a></h1><blockquote><p>整理自：穷忙陷阱：你为何越努力越原地踏步？</p></blockquote><hr><h2 id="核心观点" tabindex="-1">核心观点 <a class="header-anchor" href="#核心观点" aria-label="Permalink to &quot;核心观点&quot;">​</a></h2><blockquote><p>用战术上的勤奋，掩盖战略上的懒惰。</p></blockquote><p>穷人与富人的差距，不在于银行卡数字，而在于<strong>认知带宽的分配</strong>：</p><ul><li>穷忙族：用带宽应付琐事、追求短期快感</li><li>顶级玩家：用带宽做减法、找目标，享受长期复利</li></ul><hr><h2 id="陷阱一-假装高效的-多线程-工作" tabindex="-1">陷阱一：假装高效的&quot;多线程&quot;工作 <a class="header-anchor" href="#陷阱一-假装高效的-多线程-工作" aria-label="Permalink to &quot;陷阱一：假装高效的&quot;多线程&quot;工作&quot;">​</a></h2><h3 id="真相" tabindex="-1">真相 <a class="header-anchor" href="#真相" aria-label="Permalink to &quot;真相&quot;">​</a></h3><p>大脑无法真正&quot;多线程&quot;工作，所谓一心多用只是在任务间<strong>低效切换</strong>，消耗宝贵的脑力。看似高效，实则是最隐蔽的时间杀手。</p><p><strong>多线程的认知成本：</strong></p><ul><li>每次切换任务，大脑需要 5-15 分钟重新进入状态（&quot;注意力残留&quot;效应，Sophie Leroy 提出）</li><li>每天被打断 3 次，有效工作时长可能只剩 30%</li><li>Email/IM 即时回复文化：制造了&quot;忙碌的幻觉&quot;，但深度思考才是核心竞争力</li></ul><p><strong>穷忙族的典型症状：</strong></p><ul><li>每天处理上百封邮件，却没时间做一件真正重要的事</li><li>会议连轴转，但会议纪要从来不落实</li><li>一直在&quot;救火&quot;，从来没时间&quot;防火&quot;</li></ul><h3 id="破局-聚焦策略" tabindex="-1">破局：聚焦策略 <a class="header-anchor" href="#破局-聚焦策略" aria-label="Permalink to &quot;破局：聚焦策略&quot;">​</a></h3><blockquote><p>与其把100瓦的能量分散成多个15瓦的灯泡，不如汇聚成一把能切割钢板的<strong>激光刀</strong>。</p></blockquote><p><strong>巴菲特25/5法则：</strong></p><ol><li>写下25个目标</li><li>圈出最重要的5个</li><li>像躲避瘟疫一样<strong>坚决避开</strong>剩下的20个，直到完成前5个</li></ol><p><strong>时间块工作法（Deep Work 实践版）：</strong></p><ul><li>每天设定 2-3 个&quot;神圣时间块&quot;（每块 90-120 分钟），用于处理最重要的事</li><li>时间块内不查邮件、不回消息、不断人</li><li>其余时间统一处理碎片事务</li></ul><p><strong>艾森豪威尔矩阵实战：</strong></p><table tabindex="0"><thead><tr><th></th><th>紧急</th><th>不紧急</th></tr></thead><tbody><tr><td><strong>重要</strong></td><td>🔴 立刻做（危机/死线）</td><td>🟢 计划做（战略/成长）</td></tr><tr><td><strong>不重要</strong></td><td>🟡 委托做（他人的紧急）</td><td>⚫ 删除做（伪忙碌）</td></tr></tbody></table><p><strong>关键原则：</strong> 不紧急但重要的事不做，永远不会有时间做。</p><hr><h2 id="陷阱二-机会主义的-伪成长" tabindex="-1">陷阱二：机会主义的&quot;伪成长&quot; <a class="header-anchor" href="#陷阱二-机会主义的-伪成长" aria-label="Permalink to &quot;陷阱二：机会主义的&quot;伪成长&quot;&quot;">​</a></h2><h3 id="真相-1" tabindex="-1">真相 <a class="header-anchor" href="#真相-1" aria-label="Permalink to &quot;真相&quot;">​</a></h3><p>看到什么火就学什么——炒股、做自媒体、学AI——都浅尝辄止。这不是拥抱变化，而是<strong>机会主义的浮躁</strong>。没有在一个领域深耕，所有努力都变成无法收回的<strong>沉没成本</strong>。</p><p><strong>伪成长的五种表现：</strong></p><table tabindex="0"><thead><tr><th>症状</th><th>真实原因</th></tr></thead><tbody><tr><td>收藏夹里有1000篇文章，从没重读过</td><td>制造&quot;我在学习&quot;的幻觉</td></tr><tr><td>同时追3个技能方向，哪个都没突破</td><td>没有核心能力，什么都能被替代</td></tr><tr><td>每年立 flag，每年倒</td><td>目标太大，没有拆解到每日行动</td></tr><tr><td>各种训练营都参加了，能力还是原地踏步</td><td>只输入不输出，只学不用</td></tr><tr><td>认识很多人，但没有一个人能在关键时刻帮你</td><td>人脉是价值交换，不是认识就等于关系</td></tr></tbody></table><p><strong>沉没成本谬误：</strong> &quot;我已经在这个方向上花了3个月，不能放弃&quot;——这是最贵的借口。正确的逻辑是：<strong>只考虑从现在起，这件事值不值得继续做。</strong></p><h3 id="破局-坚守-能力圈" tabindex="-1">破局：坚守&quot;能力圈&quot; <a class="header-anchor" href="#破局-坚守-能力圈" aria-label="Permalink to &quot;破局：坚守&quot;能力圈&quot;&quot;">​</a></h3><p><strong>能力圈原则：</strong> 只做自己真正理解和擅长的事。你永远赚不到认知以外的钱。</p><p><strong>深耕的临界点：</strong></p><ul><li>任何领域，1万小时才能成为专家</li><li>但前100小时是最难的（新手甜蜜期后、平台期前最易放弃）</li><li>熬过1000小时，才能开始享受复利</li></ul><p><strong>人脉的本质：</strong> 人脉是<strong>价值交换</strong>。当你成为某个领域的专家，有效人脉会自动向你靠拢。打造自己永远胜过取悦任何人。</p><p><strong>&quot;利他是最好的利己&quot; 实操版：</strong></p><ol><li>在一个领域做到前 20%（不用第一，有足够影响力）</li><li>主动输出你的经验和思考（写文章、做分享）</li><li>帮助别人解决问题（但不讨好）</li><li>价值到位了，人脉自然来</li></ol><hr><h2 id="陷阱三-消耗精力的-情绪内耗" tabindex="-1">陷阱三：消耗精力的&quot;情绪内耗&quot; <a class="header-anchor" href="#陷阱三-消耗精力的-情绪内耗" aria-label="Permalink to &quot;陷阱三：消耗精力的&quot;情绪内耗&quot;&quot;">​</a></h2><h3 id="真相-2" tabindex="-1">真相 <a class="header-anchor" href="#真相-2" aria-label="Permalink to &quot;真相&quot;">​</a></h3><p>遇到问题第一反应是抱怨，看到别人成功就嫉妒。这种负能量让你沉浸在&quot;受害者&quot;角色中，获得暂时解脱，却唯独忘了<strong>所有问题都只能靠自己解决</strong>。</p><p><strong>情绪内耗的三种最常见模式：</strong></p><table tabindex="0"><thead><tr><th>模式</th><th>表现</th><th>代价</th></tr></thead><tbody><tr><td><strong>抱怨循环</strong></td><td>每天花 30 分钟和同事吐槽公司/老板/行业</td><td>抱怨会上瘾，越抱怨越觉得无力改变</td></tr><tr><td><strong>比较陷阱</strong></td><td>朋友圈/社交媒体看别人光鲜，对比自己焦虑</td><td>永远有人比你强，比较没有尽头</td></tr><tr><td><strong>后悔回放</strong></td><td>反复纠结&quot;当初要是……就好了&quot;</td><td>后悔不产生价值，消耗当下行动力</td></tr></tbody></table><p><strong>抱怨的神经科学：</strong></p><ul><li>抱怨会激活大脑的&quot;压力回路&quot;，让人短暂感觉好（因为获得了认同和同情）</li><li>但长期抱怨会重塑大脑，使其更容易关注负面信息（&quot;负面偏见&quot;）</li><li>结果：越抱怨越焦虑，越焦虑越抱怨，恶性循环</li></ul><h3 id="破局-启动-内部计分卡" tabindex="-1">破局：启动&quot;内部计分卡&quot; <a class="header-anchor" href="#破局-启动-内部计分卡" aria-label="Permalink to &quot;破局：启动&quot;内部计分卡&quot;&quot;">​</a></h3><ul><li>只为自己的进步和标准打分，不活在别人的眼光里</li><li><strong>芒格论嫉妒：</strong> 嫉妒是唯一一种你完全无法从中获得任何乐趣的罪过</li><li><strong>高手思维：</strong> 从不抱怨，而是研究别人如何把事情搞砸，从中学习并避开同样的坑</li></ul><p><strong>停止抱怨的实操方法：</strong></p><ol><li><strong>察觉触发词：</strong> 当想说&quot;他就是运气好&quot;&quot;这不公平&quot;时，停下来</li><li><strong>转化为问题：</strong> &quot;我能从中学到什么？&quot;&quot;下次遇到类似情况我怎么做更好？&quot;</li><li><strong>设定抱怨配额：</strong> 每周最多抱怨 15 分钟（超出则强制停止）</li><li><strong>建立&quot;已完成&quot;日志：</strong> 每天记录 3 件自己做好的事，强化正向回路</li></ol><hr><h2 id="终极心法-种下-目标之树" tabindex="-1">终极心法：种下&quot;目标之树&quot; <a class="header-anchor" href="#终极心法-种下-目标之树" aria-label="Permalink to &quot;终极心法：种下&quot;目标之树&quot;&quot;">​</a></h2><blockquote><p>人生就像射箭，没有靶子，拉弓毫无意义。</p></blockquote><p>当你在心里种下一棵需要10年、20年才能长成的<strong>目标之树</strong>时：</p><ul><li>所有决策和专注自动围绕它进行</li><li>短期诱惑便不值一提</li><li>战略清晰后，战术执行才有效</li></ul><p><strong>目标设定的SMART原则（升级版）：</strong></p><table tabindex="0"><thead><tr><th>要素</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td>S-Specific</td><td>具体</td><td>不是&quot;我要变强&quot;，而是&quot;我要在风电行业成为风资源评估专家&quot;</td></tr><tr><td>M-Measurable</td><td>可衡量</td><td>不是&quot;多读书&quot;，而是&quot;每周读完1本书并写300字读书笔记&quot;</td></tr><tr><td>A-Ambitious</td><td>有野心</td><td>这个目标能让你早上6点自动醒来</td></tr><tr><td>R-Relevant</td><td>相关</td><td>和你的核心方向高度相关，不是随机的</td></tr><tr><td>T-Time-bound</td><td>有期限</td><td>3年后我要到达什么位置</td></tr></tbody></table><p><strong>10-10-10法则（决策框架）：</strong></p><ul><li>这个决定，10分钟后会怎样？→ 影响不大</li><li>10个月后会怎样？→ 有一定影响</li><li>10年后会怎样？→ 真正重要的事才能穿越这个时间窗口</li></ul><hr><h2 id="诊断-你陷入穷忙了吗" tabindex="-1">诊断：你陷入穷忙了吗？ <a class="header-anchor" href="#诊断-你陷入穷忙了吗" aria-label="Permalink to &quot;诊断：你陷入穷忙了吗？&quot;">​</a></h2><p><strong>穷忙自测表（每项1分）：</strong></p><ul><li>[ ] 每天很忙，但晚上想不起来今天做了什么重要的事</li><li>[ ] 同时在追3个以上的&quot;风口&quot;或技能方向</li><li>[ ] 手机从不离手，随时回复消息</li><li>[ ] 经常说&quot;等我有空了再……&quot;，但从来没空</li><li>[ ] 每周开会超过20小时，但没有跟进任何会议结论</li><li>[ ] 睡前刷手机到深夜，感觉越休息越累</li><li>[ ] 对现状不满，但没有明确的改变计划</li><li>[ ] 经常同时处理多件事（邮件/微信/工作同时进行）</li></ul><p><strong>评分结果：</strong></p><ul><li>0-2分：状态良好，保持现状</li><li>3-5分：轻度穷忙，需要聚焦</li><li>6-8分：中度穷忙，警惕信号</li><li>9分+：重度穷忙，立即行动</li></ul><hr><h2 id="破局工具箱" tabindex="-1">破局工具箱 <a class="header-anchor" href="#破局工具箱" aria-label="Permalink to &quot;破局工具箱&quot;">​</a></h2><h3 id="工具一-每日三件事法则" tabindex="-1">工具一：每日三件事法则 <a class="header-anchor" href="#工具一-每日三件事法则" aria-label="Permalink to &quot;工具一：每日三件事法则&quot;">​</a></h3><p>每天早上问自己：&quot;今天哪3件事做完，今天就没有白过？&quot;</p><p><strong>原则：</strong></p><ul><li>最多3件，写在纸上</li><li>优先做最难/最重要的那件</li><li>做完3件后，多做的都是奖励</li></ul><h3 id="工具二-周复盘模板-15分钟" tabindex="-1">工具二：周复盘模板（15分钟） <a class="header-anchor" href="#工具二-周复盘模板-15分钟" aria-label="Permalink to &quot;工具二：周复盘模板（15分钟）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本周做得好的（2件）：</span></span>
<span class="line"><span>1.</span></span>
<span class="line"><span>2.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>本周可以改进的（2件）：</span></span>
<span class="line"><span>1.</span></span>
<span class="line"><span>2.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>下周最重要的3件事：</span></span>
<span class="line"><span>1.</span></span>
<span class="line"><span>2.</span></span>
<span class="line"><span>3.</span></span></code></pre></div><h3 id="工具三-能量管理优先级" tabindex="-1">工具三：能量管理优先级 <a class="header-anchor" href="#工具三-能量管理优先级" aria-label="Permalink to &quot;工具三：能量管理优先级&quot;">​</a></h3><p>不是所有时间都有同样的价值。识别你的<strong>能量高峰期</strong>（有人是早晨，有人是深夜），把最重要的事放在能量最高的时间段。</p><table tabindex="0"><thead><tr><th>能量状态</th><th>适合做的事</th></tr></thead><tbody><tr><td>高能量/高专注</td><td>深度思考、战略规划、创造性工作</td></tr><tr><td>中能量/中专注</td><td>沟通协调、会议执行、常规事务</td></tr><tr><td>低能量/低专注</td><td>邮件回复、信息浏览、碎片处理</td></tr></tbody></table><h3 id="工具四-说-不-的公式" tabindex="-1">工具四：说&quot;不&quot;的公式 <a class="header-anchor" href="#工具四-说-不-的公式" aria-label="Permalink to &quot;工具四：说&quot;不&quot;的公式&quot;">​</a></h3><p>当一个新任务/邀请过来时：</p><blockquote><p>&quot;我很想帮你，但目前我在做 [当前最重要的2件事]，如果加了这件事，我担心 [会受影响的那件重要的事]。&quot;</p></blockquote><ul><li>不需要解释太多细节</li><li>不需要道歉</li><li>给对方一个替代方案更好（&quot;你可以找XXX&quot;）</li></ul><hr><h2 id="真实案例-从穷忙到高效的人生转变" tabindex="-1">真实案例：从穷忙到高效的人生转变 <a class="header-anchor" href="#真实案例-从穷忙到高效的人生转变" aria-label="Permalink to &quot;真实案例：从穷忙到高效的人生转变&quot;">​</a></h2><h3 id="案例一-咨询顾问的觉醒" tabindex="-1">案例一：咨询顾问的觉醒 <a class="header-anchor" href="#案例一-咨询顾问的觉醒" aria-label="Permalink to &quot;案例一：咨询顾问的觉醒&quot;">​</a></h3><p><strong>背景：</strong> 某咨询公司项目经理，每天工作14小时，周末也在处理邮件，晋升前夜突然裸辞。</p><p><strong>诊断：</strong> 她陷入了&quot;忙碌=重要&quot;的认知陷阱。老板和客户之所以给她更多工作，恰恰是因为她从不拒绝。她以为自己越忙越不可替代，实际上越忙越没有时间思考战略和提升。</p><p><strong>转变：</strong> 辞职后Gap 3个月，重新梳理自己真正想要的职业路径。现在做独立顾问，年收入是原来的1/3，但每天只工作6小时，有了大量时间陪伴家人和自我成长。</p><p><strong>关键转折：</strong> 不是更努力地工作，而是更聪明地选择——找到&quot;不做什么&quot;。</p><h3 id="案例二-中年转型的销售总监" tabindex="-1">案例二：中年转型的销售总监 <a class="header-anchor" href="#案例二-中年转型的销售总监" aria-label="Permalink to &quot;案例二：中年转型的销售总监&quot;">​</a></h3><p><strong>背景：</strong> 40岁，传统行业销售干了15年，行业下行被裁员，找不到合适工作。</p><p><strong>诊断：</strong> 他的能力高度绑定在&quot;关系&quot;上，但这种关系只在他的圈子里有效。他忽视了在整个职业生涯中，没有建立可迁移的能力。</p><p><strong>转变：</strong> 重新定义自己——不是&quot;销售&quot;，而是&quot;帮助B2B企业优化供应链效率的专家&quot;。把过去的销售经验重新包装为&quot;解决方案能力&quot;，成功转型为企业咨询顾问。</p><p><strong>关键转折：</strong> 不是找一份新工作，而是重新定义自己能解决什么问题。</p><h3 id="案例三-自媒体博主的-去杠杆化" tabindex="-1">案例三：自媒体博主的&quot;去杠杆化&quot; <a class="header-anchor" href="#案例三-自媒体博主的-去杠杆化" aria-label="Permalink to &quot;案例三：自媒体博主的&quot;去杠杆化&quot;&quot;">​</a></h3><p><strong>背景：</strong> 某知识博主同时做10个平台的内容，日更3条视频，粉丝数看起来很多，但变现寥寥，身体还搞垮了。</p><p><strong>诊断：</strong> 他把&quot;勤奋&quot;和&quot;有效&quot;混为一谈。在每个平台都浅尝辄止，没有在一个平台建立足够的影响力。10个平台的粉丝加起来，不如一个平台的5万铁粉值钱。</p><p><strong>转变：</strong> 聚焦1个平台，深耕1个垂直领域，停止日更，提高内容质量。粉丝少了60%，但广告报价涨了3倍，变现效率反而更高。</p><p><strong>关键转折：</strong> 不是做更多，而是做得更少、更好。</p><hr><h2 id="历史规律-每一代人的-穷忙-都不同" tabindex="-1">历史规律：每一代人的&quot;穷忙&quot;都不同 <a class="header-anchor" href="#历史规律-每一代人的-穷忙-都不同" aria-label="Permalink to &quot;历史规律：每一代人的&quot;穷忙&quot;都不同&quot;">​</a></h2><p><strong>工业革命时代（19世纪）：</strong></p><ul><li>穷忙：每天12小时重复体力劳动，没有时间提升</li><li>对策：8小时工作制 + 义务教育</li></ul><p><strong>白领时代（20世纪）：</strong></p><ul><li>穷忙：办公室政治 + 文山会海 + 效率低下</li><li>对策：MBA管理 + 流程优化 + 项目管理</li></ul><p><strong>信息爆炸时代（2000-2020）：</strong></p><ul><li>穷忙：信息过载 + 注意力碎片化 + 社交媒体焦虑</li><li>对策：深度工作 + 极简主义 + 专注力训练</li></ul><p><strong>AI时代（2020-）：</strong></p><ul><li>穷忙：AI焦虑 + 技能迭代加速 + 35岁/40岁危机</li><li>对策：建立AI无法替代的核心能力 + 终身学习 + 战略聚焦</li></ul><p><strong>每一代人的共同规律：</strong> 低效的忙碌永远存在，但破局的方法论是通用的——<strong>在正确的方向上持续努力，而不是在错误的方向上越努力越迷路。</strong></p><hr><h2 id="芒格-巴菲特体系的核心原则" tabindex="-1">芒格/巴菲特体系的核心原则 <a class="header-anchor" href="#芒格-巴菲特体系的核心原则" aria-label="Permalink to &quot;芒格/巴菲特体系的核心原则&quot;">​</a></h2><blockquote><p>本文的底层思想大量借鉴了芒格/巴菲特的投资与人生哲学，以下是核心原则的提炼：</p></blockquote><h3 id="原则一-逆向思维" tabindex="-1">原则一：逆向思维 <a class="header-anchor" href="#原则一-逆向思维" aria-label="Permalink to &quot;原则一：逆向思维&quot;">​</a></h3><p>&quot;如果我知道我会死在哪里，我就永远不去那个地方。&quot;</p><ul><li>不是问&quot;我怎样才能成功&quot;，而是问&quot;失败的人通常做了哪些事？&quot;</li><li>穷忙陷阱就是典型的&quot;成功路径不清晰，但失败路径很明确&quot;的领域</li></ul><h3 id="原则二-能力圈思维" tabindex="-1">原则二：能力圈思维 <a class="header-anchor" href="#原则二-能力圈思维" aria-label="Permalink to &quot;原则二：能力圈思维&quot;">​</a></h3><p>&quot;如果你知道了能力圈的边界，你就会比那些不知道边界的人强大得多。&quot;</p><ul><li>不做能力圈外的事</li><li>在能力圈内，做到极致</li></ul><h3 id="原则三-长期主义" tabindex="-1">原则三：长期主义 <a class="header-anchor" href="#原则三-长期主义" aria-label="Permalink to &quot;原则三：长期主义&quot;">​</a></h3><p>&quot;没有人愿意慢慢变富。&quot;</p><ul><li>复利的核心不是利率，而是时间</li><li>10年种一棵树，和10年追10个风口，结果天壤之别</li></ul><h3 id="原则四-极度理性" tabindex="-1">原则四：极度理性 <a class="header-anchor" href="#原则四-极度理性" aria-label="Permalink to &quot;原则四：极度理性&quot;">​</a></h3><p>&quot;我之所以能在投资上成功，不是因为我聪明，而是因为我理性。&quot;</p><ul><li>情绪是决策的天敌</li><li>内部计分卡 &gt; 外部评价</li></ul><hr><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p><strong>我是在低头砍树，还是在抬头磨斧？</strong></p></blockquote><p>如果你的答案是&quot;我在砍树&quot;：</p><ul><li>砍的树是什么？值不值得砍？</li><li>有没有更好的工具/方法？</li><li>砍完这棵树，下一棵是什么？</li></ul><p>如果你的答案是&quot;我在磨斧&quot;：</p><ul><li>这把斧头磨的方向对不对？</li><li>磨到什么时候应该去砍树？</li></ul><hr><h2 id="相关知识节点" tabindex="-1">相关知识节点 <a class="header-anchor" href="#相关知识节点" aria-label="Permalink to &quot;相关知识节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关联主题</th><th>连接点</th></tr></thead><tbody><tr><td>[[existentialism-nihilism-meaning]]</td><td>行动先于意义——没有靶子的拉弓无意义；种树与此相通</td></tr><tr><td>[[finding-life-direction]]</td><td>三圈交集找方向——和本文&quot;战略聚焦&quot;相通；SMART目标与之一致</td></tr><tr><td>[[self-motivation]]</td><td>内部计分卡 vs 外部评价体系——芒格体系的核心</td></tr><tr><td>[[happiness-comparison]]</td><td>嫉妒的反面是专注自己——芒格嫉妒论的延伸；比较陷阱与此交叉</td></tr><tr><td>[[time-management]]</td><td>（可新建）番茄钟、GTD、时间块——穷忙的对立面</td></tr><tr><td>[[ai-workplace-paradox]]</td><td>AI时代的穷忙：效率提升反被裁员——穷忙陷阱的新变种</td></tr></tbody></table><hr><blockquote><p><strong>整理日期：2026-06-22</strong><strong>扩展版本：17节 → 核心框架 + 诊断工具 + 案例 + 历史规律 + 深层哲学</strong></p></blockquote>`,135)])])}const g=o(i,[["render",n]]);export{q as __pageData,g as default};
